function liqCard(){var Q=R.liquidity,D=R.dex||{};if(!Q&&!D.liq)return '';var b=Q?Q.burnedPct:null;return '<div class="card"><h2>Liquidity</h2><div class="grid">'+kv('pool',Q?w(Q.pool):(D.pair?w(D.pair):'–'))+kv('in the pool',Q&&Q.poolSol?Q.poolSol.toFixed(1)+' SOL <small>'+usd(D.liq)+'</small>':usd(D.liq))+kv('LP tokens burned',b==null?'–':'<span class="'+(b>=99?'pos':b>=90?'':'neg')+'">'+p1(b)+'</span>')+kv('can it be pulled?',b==null?'unknown':b>=99?'<span class="pos">no — burned</span>':'<span class="neg">yes — LP is held</span>')+kv('pool created by',Q?w(Q.creator):'–')+kv('dex',esc(D.dex||'–'))+'</div>'+(Q&&Q.lpHolders&&Q.lpHolders.length&&!(b>=99)?'<div class="sub" style="margin-top:8px">LP holders: '+Q.lpHolders.map(function(x){return w(x.owner)+' '+p1(x.pctOfMinted)}).join(' · ')+'</div>':'')+'</div>'}
