  function who(r){return (r.role==='dev'?tag('dev'):r.role==='bundle'?tag('bundle'):tag('#'+r.rank,'early'))+' '+w(r.wallet)+(r.group?' '+tag('owner '+r.group,'grp'):'')+((r.paidBy||[]).length?' <small>bought with SOL from '+r.paidBy.map(function(x){return (x.role==='dev'?'the dev':x.role==='bundle'?'bundle wallet':x.rank?'first buyer #'+x.rank:'wallet')+' '+w(x.wallet)+(x.via?' through '+w(x.via):'')+' '+txl(x.sig)}).join(', ')+'</small>':'')+(r.histPartial?' <small style="color:var(--amb)">history cut</small>':'')}
  var isH=function(r){return r.side.length||r.back.length||(r.paidBy||[]).length},hid=T.rows.filter(isH),rest=T.rows.filter(function(r){return !isH(r)});
