  if(R.cat&&R.pie){var P={dev:0,linked:0,side:0,probable:0,first:0,groups:0,top:0};for(var k in R.cat){var v=j.balances[k];if(v==null){var x=(R.window||[]).concat(R.side||[]).find(function(q){return q.wallet===k});v=x?x.nowPct||0:0}P[R.cat[k]]+=v}P.pool=j.poolPct!=null?j.poolPct:R.pie.pool;var used=0;for(var z in P)used+=P[z];P.rest=Math.max(0,100-used);R.pie=P;if($('pie'))$('pie').innerHTML=pie3d(P);if($('leg'))$('leg').innerHTML=legend(P);if($('tiles'))$('tiles').innerHTML=tilesHtml()}
  if(R.windowSummary&&$('whn'))$('whn').textContent=p1((R.window||[]).reduce(function(a,p){return a+(p.nowPct||0)},0));
