  if(j.trades&&j.trades.length){FEED=j.trades.concat(FEED).slice(0,150);$('feed').innerHTML=FEED.map(function(t){return '<tr><td class="l">'+uk(t.ts).replace(' UK','').slice(-8)+'</td><td class="l">'+w(t.wallet)+'</td><td class="l">'+tags(t)+'</td><td class="l '+(t.kind==='buy'?'pos':'neg')+'">'+t.kind+'</td><td>'+t.sol+'</td><td>'+p1(t.pct)+'</td></tr>'}).join('')}
